<?php
 namespace Pterodactyl\Http\Requests\Api\Client\Servers\Addons; use Pterodactyl\Models\Server; use Pterodactyl\Models\Permission; class ModpackInstallRequest extends AddonRequest { public function permission(): string { return Permission::ACTION_FILE_CREATE; } public function authorize(): bool { $server = $this->route()->parameter('server'); if (!$server instanceof Server || !parent::authorize()) { return false; } return $this->user()->can(Permission::ACTION_FILE_DELETE, $server) && $this->user()->can(Permission::ACTION_CONTROL_STOP, $server) && $this->user()->can(Permission::ACTION_CONTROL_START, $server) && $this->user()->can(Permission::ACTION_STARTUP_UPDATE, $server); } } 